import{_ as a,a as s}from"./chunks/public-page.Cis11Pa3.js";import{_ as t,c as r,o as n,a2 as i}from"./chunks/framework.PGES7OoM.js";const m=JSON.parse('{"title":"Receive assets privately","description":"","frontmatter":{"rawMarkdown":"# Receive assets privately\\n\\nOne of the most unique things about Curvy is how easy it is to share payment instructions with senders.\\n\\nPeople sending you assets never need to know what Curvy is, how it works, or to open the Curvy App.\\nThey just need to copy and paste your public URL or ENS address (which is also ideally very easy to remember).\\n\\n> [!TIP]\\n> You can receive assets on any network listed in the [supported networks](/for-users/#supported-networks-and-tokens). Curvy will automatically bridge your funds using LiFi and shield them on Arbitrum.\\n\\nBelow are three ways you can share payment instructions with senders so that you can receive assets automatically shielded in Curvy.\\n\\n## By sharing your ENS\\n\\nThe easiest way for someone to send you assets is by using your Curvy ID in an ENS-compatible wallet such as Rabby or MetaMask.\\n\\nThe sender can simply enter your Curvy ID as the recipient for a new transaction:\\n\\n![Using Curvy name in Metamask](ens-metamask.png)\\n\\n## By sharing your public URL\\n\\nIf the sender\'s wallet doesn\'t support ENS, they can always open your public URL\\n\\n```\\nhttps://your-curvy-id.curvy.name\\n```\\n\\nand copy the generated address to the wallet of their choice.\\n\\nAn example with [https://travica.curvy.name](https://travica.curvy.name):\\n\\n![Public page](public-page.png)\\n\\n## By generating a private address\\n\\nIf you are, for example, withdrawing funds from an exchange, you will not be able to enter the ENS as the withdrawal address or send a URL through a message, as it\'s an automated process.\\n\\nIn this case, you\'d simply follow the steps explained above in [\\"By sharing your public URL\\"](#by-sharing-your-public-url)\\nand copy the newly generated private address to the withdrawal form.\\n","rawMarkdownPath":"/_raw/for-users/receive-assets-privately.md","rawMarkdownTitle":"Receive assets privately","rawMarkdownUrl":"https://docs.curvy.box/_raw/for-users/receive-assets-privately.md"},"headers":[],"relativePath":"for-users/receive-assets-privately.md","filePath":"for-users/receive-assets-privately.md","lastUpdated":1784117553000}'),o={name:"for-users/receive-assets-privately.md"};function u(p,e,l,y,h,d){return n(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="receive-assets-privately" tabindex="-1">Receive assets privately <a class="header-anchor" href="#receive-assets-privately" aria-label="Permalink to &quot;Receive assets privately&quot;">​</a></h1><p>One of the most unique things about Curvy is how easy it is to share payment instructions with senders.</p><p>People sending you assets never need to know what Curvy is, how it works, or to open the Curvy App. They just need to copy and paste your public URL or ENS address (which is also ideally very easy to remember).</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>You can receive assets on any network listed in the <a href="/for-users/#supported-networks-and-tokens">supported networks</a>. Curvy will automatically bridge your funds using LiFi and shield them on Arbitrum.</p></div><p>Below are three ways you can share payment instructions with senders so that you can receive assets automatically shielded in Curvy.</p><h2 id="by-sharing-your-ens" tabindex="-1">By sharing your ENS <a class="header-anchor" href="#by-sharing-your-ens" aria-label="Permalink to &quot;By sharing your ENS&quot;">​</a></h2><p>The easiest way for someone to send you assets is by using your Curvy ID in an ENS-compatible wallet such as Rabby or MetaMask.</p><p>The sender can simply enter your Curvy ID as the recipient for a new transaction:</p><p><img src="'+a+'" alt="Using Curvy name in Metamask"></p><h2 id="by-sharing-your-public-url" tabindex="-1">By sharing your public URL <a class="header-anchor" href="#by-sharing-your-public-url" aria-label="Permalink to &quot;By sharing your public URL&quot;">​</a></h2><p>If the sender&#39;s wallet doesn&#39;t support ENS, they can always open your public URL</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://your-curvy-id.curvy.name</span></span></code></pre></div><p>and copy the generated address to the wallet of their choice.</p><p>An example with <a href="https://travica.curvy.name" target="_blank" rel="noreferrer">https://travica.curvy.name</a>:</p><p><img src="'+s+'" alt="Public page"></p><h2 id="by-generating-a-private-address" tabindex="-1">By generating a private address <a class="header-anchor" href="#by-generating-a-private-address" aria-label="Permalink to &quot;By generating a private address&quot;">​</a></h2><p>If you are, for example, withdrawing funds from an exchange, you will not be able to enter the ENS as the withdrawal address or send a URL through a message, as it&#39;s an automated process.</p><p>In this case, you&#39;d simply follow the steps explained above in <a href="#by-sharing-your-public-url">&quot;By sharing your public URL&quot;</a> and copy the newly generated private address to the withdrawal form.</p>',18)])])}const w=t(o,[["render",u]]);export{m as __pageData,w as default};
